import{_ as a,o as l,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"স্বাস্থ্যসেবা নিশ্চয়তা আইন","description":"","frontmatter":{},"headers":[],"relativePath":"bn/44-医疗保障法.md","filePath":"bn/44-医疗保障法.md"}'),i={name:"bn/44-医疗保障法.md"};function e(o,t,h,n,s,_){return l(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="স্বাস্থ্যসেবা-নিশ্চয়তা-আইন" tabindex="-1">স্বাস্থ্যসেবা নিশ্চয়তা আইন <a class="header-anchor" href="#স্বাস্থ্যসেবা-নিশ্চয়তা-আইন" aria-label="Permalink to &quot;স্বাস্থ্যসেবা নিশ্চয়তা আইন&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>44</td></tr><tr><td>মডিউল</td><td>আইনি ব্যবস্থা এবং প্রশাসনিক কাঠামো</td></tr><tr><td>মূল কীওয়ার্ড</td><td>স্বাস্থ্যসেবা অধিকার, সিম্বায়োসিস স্বাস্থ্যসেবা, সাধনা ক্ষতি চিকিৎসা, জীবন স্বাস্থ্য, স্বাস্থ্য বীমা ব্যবস্থা</td></tr></tbody></table><h2 id="_1-আইন-প্রণয়নের-উদ্দেশ্য-এবং-মূল-নীতি" tabindex="-1">1. আইন প্রণয়নের উদ্দেশ্য এবং মূল নীতি <a class="header-anchor" href="#_1-আইন-প্রণয়নের-উদ্দেশ্য-এবং-মূল-নীতি" aria-label="Permalink to &quot;1. আইন প্রণয়নের উদ্দেশ্য এবং মূল নীতি&quot;">​</a></h2><p>《স্বাস্থ্যসেবা নিশ্চয়তা আইন》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার পাঁচটি সহায়ক আইনের একটি, এবং এর উদ্দেশ্য হল হেঙ্গুয়ানঝৌর ভেতরে সমস্ত জীবের স্বাস্থ্য অধিকার এবং স্বাস্থ্যসেবা অধিকার নিশ্চিত করা, সকল প্রজাতিকে কভার করা সিম্বায়োসিস স্বাস্থ্যসেবা ব্যবস্থা স্থাপন করা, এবং নিশ্চিত করা যে প্রতিটি জীব অসুস্থ বা আহত হলে সময়মতো, কার্যকর চিকিৎসা পেতে পারে।</p><p>এই আইন নিম্নলিখিত মূল নীতি স্থাপন করে:</p><table tabindex="0"><thead><tr><th>নীতি</th><th>অন্তর্নিহিত অর্থ</th></tr></thead><tbody><tr><td>স্বাস্থ্য অগ্রাধিকার নীতি</td><td>জীবন স্বাস্থ্য হল সমস্ত বিবর্তনের ভিত্তি, রাষ্ট্র এবং সভ্যতা জীবন স্বাস্থ্যের নিশ্চয়তাকে অগ্রাধিকারে রাখে</td></tr><tr><td>সর্বজনীন কভারেজ নীতি</td><td>স্বাস্থ্যসেবা নিশ্চয়তা সমস্ত জীবকে কভার করে, প্রজাতি, সাধনার স্তর, উত্স এবং আর্থিক অবস্থা নির্বিশেষে</td></tr><tr><td>স্তরবিন্যাস চিকিৎসা নীতি</td><td>প্রাথমিক স্বাস্থ্যসেবা, আঞ্চলিক স্বাস্থ্যসেবা, উচ্চস্তরের স্বাস্থ্যসেবা তিন-স্তরের চিকিৎসা ব্যবস্থা স্থাপন করা, স্বাস্থ্যসেবা সম্পদ যুক্তিসঙ্গতভাবে বণ্টন করা</td></tr><tr><td>প্রতিরোধ এবং চিকিৎসা একীভূত নীতি</td><td>প্রতিরোধ প্রধান, প্রতিরোধ এবং চিকিৎসা একীভূত, সাধনা ক্ষতির প্রতিরোধ এবং পুনর্বাসনকে গুরুত্ব দেওয়া</td></tr><tr><td>বিদেশী প্রজাতির অভিযোজন নীতি</td><td>বিভিন্ন প্রজাতির শারীরিক বৈশিষ্ট্য অনুযায়ী অভিযোজিত স্বাস্থ্যসেবা পরিকল্পনা প্রদান করা, মানব প্রজাতির মানদণ্ড দিয়ে একই রকম করা নিষিদ্ধ</td></tr><tr><td>জনকল্যাণ বৈশিষ্ট্য নীতি</td><td>মৌলিক স্বাস্থ্যসেবা সেবার জনকল্যাণ বৈশিষ্ট্য রয়েছে, লাভের উদ্দেশ্যে জীবনের চিকিৎসা অধিকার কেড়ে নেওয়া যাবে না</td></tr></tbody></table><h2 id="_2-জীবন-স্বাস্থ্য-অধিকারের-আইনি-নিশ্চয়তা" tabindex="-1">2. জীবন স্বাস্থ্য অধিকারের আইনি নিশ্চয়তা <a class="header-anchor" href="#_2-জীবন-স্বাস্থ্য-অধিকারের-আইনি-নিশ্চয়তা" aria-label="Permalink to &quot;2. জীবন স্বাস্থ্য অধিকারের আইনি নিশ্চয়তা&quot;">​</a></h2><p>এই আইন স্পষ্টভাবে নির্ধারণ করে যে, জীবন স্বাস্থ্য অধিকার হল সিম্বায়োসিস সংবিধান দ্বারা প্রতিটি জীবকে প্রদত্ত মৌলিক অধিকার, এবং এর মধ্যে নির্দিষ্টভাবে অন্তর্ভুক্ত:</p><ol><li><strong>মৌলিক স্বাস্থ্যসেবা অধিকার</strong>: প্রতিটি জীব বিনামূল্যে মৌলিক স্বাস্থ্যসেবা সেবা পাওয়ার অধিকার রাখে, যার মধ্যে সাধারণ রোগের নির্ণয় ও চিকিৎসা, মৌলিক ওষুধ, নিয়মিত স্বাস্থ্য পরীক্ষা ইত্যাদি অন্তর্ভুক্ত।</li><li><strong>জরুরী চিকিৎসা অধিকার</strong>: প্রতিটি জীব আকস্মিক অসুস্থতা বা আঘাতের সময় জরুরী চিকিৎসা পাওয়ার অধিকার রাখে, স্বাস্থ্যসেবা প্রতিষ্ঠান কোনো কারণেই জরুরী চিকিৎসা প্রত্যাখ্যান করতে পারবে না।</li><li><strong>সাধনা ক্ষতি চিকিৎসা অধিকার</strong>: সাধক সাধনার প্রক্রিয়ায় যে শক্তি ব্যাকুল্য, নাড়ি ক্ষতি, ম ental breakdown ইত্যাদি ক্ষতি গ্রস্ত হয়, তার পেশাদার চিকিৎসা পাওয়ার অধিকার রাখে।</li><li><strong>জ্ঞাত সম্মতি অধিকার</strong>: রোগী নিজের অবস্থা, চিকিৎসা পরিকল্পনা, ঝুঁকি এবং পূর্বাভাস সম্পর্কে জানার অধিকার রাখে, এবং চিকিৎসা পরিকল্পনা বেছে নেওয়া বা প্রত্যাখ্যান করার অধিকার রাখে।</li><li><strong>গোপনীয়তা সুরক্ষা অধিকার</strong>: রোগীর স্বাস্থ্যসেবা তথ্য এবং শরীরের ডেটা আইন দ্বারা সুরক্ষিত, রোগীর সম্মতি ছাড়া ফাঁস বা অন্য উদ্দেশ্যে ব্যবহার করা যাবে না।</li><li><strong>পুনর্বাসন নিশ্চয়তা অধিকার</strong>: অসুস্থ বা আহত রোগী পুনর্বাসন চিকিৎসা এবং সহায়ক যন্ত্রপাতি পাওয়ার অধিকার রাখে, যা তাকে শ্রম এবং জীবনযাত্রার ক্ষমতা পুনরুদ্ধার করতে সহায়তা করে।</li></ol><h2 id="_3-সিম্বায়োসিস-স্বাস্থ্যসেবা-ব্যবস্থার-কাঠামো" tabindex="-1">3. সিম্বায়োসিস স্বাস্থ্যসেবা ব্যবস্থার কাঠামো <a class="header-anchor" href="#_3-সিম্বায়োসিস-স্বাস্থ্যসেবা-ব্যবস্থার-কাঠামো" aria-label="Permalink to &quot;3. সিম্বায়োসিস স্বাস্থ্যসেবা ব্যবস্থার কাঠামো&quot;">​</a></h2><p>অ্যাঙ্কার সিম্বায়োসিস সভ্যতার স্বাস্থ্যসেবা ব্যবস্থা তিনটি স্তরে বিভক্ত, এবং প্রতিটি স্তরের মধ্যে রেফারেল এবং সহযোগিতা ব্যবস্থা স্থাপন করা হয়েছে:</p><table tabindex="0"><thead><tr><th>স্তর</th><th>নাম</th><th>কার্য</th><th>কভারেজ পরিসর</th></tr></thead><tbody><tr><td>প্রথম স্তর</td><td>প্রাথমিক স্বাস্থ্যসেবা কেন্দ্র</td><td>সাধারণ রোগের নির্ণয় ও চিকিৎসা, প্রতিরোধমূলক স্বাস্থ্যসেবা, মৌলিক স্বাস্থ্য পরীক্ষা, জরুরী স্থানান্তর</td><td>কমিউনিটি/গ্রাম/ছোট位面</td></tr><tr><td>দ্বিতীয় স্তর</td><td>আঞ্চলিক স্বাস্থ্যসেবা কেন্দ্র</td><td>বিশেষজ্ঞ চিকিৎসা, অস্ত্রোপচার চিকিৎসা, সাধনা ক্ষতির প্রাথমিক চিকিৎসা, পুনর্বাসন</td><td>শহর/আঞ্চলিক/মাঝারি位面</td></tr><tr><td>তৃতীয় স্তর</td><td>উচ্চস্তরের স্বাস্থ্যসেবা মূল হাসপাতাল</td><td>জটিল গুরুতর রোগ, উচ্চস্তরের সাধনা ক্ষতি, চেতনা অঞ্চলের রোগ, আন্তঃপ্রজাতি জটিল রোগ</td><td>সভ্যতার কেন্দ্র/বৃহৎ位面</td></tr></tbody></table><p>এছাড়াও, &quot;সাধনা ক্ষতি বিশেষ বিভাগ&quot; স্থাপন করা হয়েছে: বিশেষভাবে সাধনার প্রক্রিয়ার বিভিন্ন ক্ষতি পরিচালনা করা, যার মধ্যে শক্তি ওভারলোড, নাড়ি ভাঙ্গা, মনোবল আক্রমণ, আত্মার ক্ষতি ইত্যাদি অন্তর্ভুক্ত, এবং সাধনা নিয়মে পারদর্শী স্বাস্থ্যসেবা কর্মী সজ্জিত করা হয়েছে।</p><h2 id="_4-স্বাস্থ্যসেবা-নিশ্চয়তা-তহবিল" tabindex="-1">4. স্বাস্থ্যসেবা নিশ্চয়তা তহবিল <a class="header-anchor" href="#_4-স্বাস্থ্যসেবা-নিশ্চয়তা-তহবিল" aria-label="Permalink to &quot;4. স্বাস্থ্যসেবা নিশ্চয়তা তহবিল&quot;">​</a></h2><p>স্বাস্থ্যসেবা নিশ্চয়তা তহবিল হল সিম্বায়োসিস স্বাস্থ্যসেবা ব্যবস্থার চালানোর আর্থিক ভিত্তি, এবং এর উৎস অন্তর্ভুক্ত:</p><ul><li>পাবলিক সঞ্চয় বরাদ্দ (প্রধান উৎস)</li><li>যৌথ উৎপাদন চুক্তি ব্যবস্থায় স্বাস্থ্যসেবা নিশ্চয়তা অংশ</li><li>সামাজিক অনুদান</li><li>তহবিল বিনিয়োগের আয়</li></ul><p>তহবিলের প্রদানের পরিসর অন্তর্ভুক্ত: মৌলিক স্বাস্থ্যসেবা সেবার খরচ, জরুরী চিকিৎসার খরচ, সাধনা ক্ষতি চিকিৎসার খরচ, মৌলিক ওষুধের খরচ, পুনর্বাসনের খরচ ইত্যাদি। রোগী ব্যক্তিগতভাবে কেবল অল্প স্ব-প্রদান খরচ প্রদান করে, এবং আর্থিক কষ্টে পড়াদের জন্য ছাড় প্রদান করা হয়।</p><h2 id="_5-স্বাস্থ্যসেবা-প্রতিষ্ঠান-এবং-স্বাস্থ্যসেবা-কর্মী" tabindex="-1">5. স্বাস্থ্যসেবা প্রতিষ্ঠান এবং স্বাস্থ্যসেবা কর্মী <a class="header-anchor" href="#_5-স্বাস্থ্যসেবা-প্রতিষ্ঠান-এবং-স্বাস্থ্যসেবা-কর্মী" aria-label="Permalink to &quot;5. স্বাস্থ্যসেবা প্রতিষ্ঠান এবং স্বাস্থ্যসেবা কর্মী&quot;">​</a></h2><ul><li><strong>পাবলিক স্বাস্থ্যসেবা প্রতিষ্ঠান</strong>: রাষ্ট্র বা সভ্যতার সম্প্রদায় দ্বারা প্রতিষ্ঠিত, মৌলিক স্বাস্থ্যসেবা সেবা এবং পাবলিক স্বাস্থ্য কার্য বহন করে, এবং তহবিল স্বাস্থ্যসেবা নিশ্চয়তা তহবিল দ্বারা নিশ্চিত করা হয়।</li><li><strong>প্রাইভেট স্বাস্থ্যসেবা প্রতিষ্ঠান</strong>: সামাজিক শক্তি দ্বারা আইন অনুযায়ী প্রতিষ্ঠিত, উচ্চস্তরের স্বাস্থ্যসেবা সেবা প্রদান করতে পারে, কিন্তু অবশ্যই স্বাস্থ্যসেবা অধিদপ্তরের তদারকি গ্রহণ করতে হবে, এবং জরুরী রোগীকে প্রত্যাখ্যান করতে পারবে না।</li><li><strong>বিদেশী প্রজাতির স্বাস্থ্যসেবা প্রতিষ্ঠান</strong>: বিশেষ প্রজাতির শারীরিক চাহিদা অনুযায়ী প্রতিষ্ঠিত বিশেষজ্ঞ স্বাস্থ্যসেবা প্রতিষ্ঠান, এবং বিদেশী প্রজাতির স্বাস্থ্যসেবা কর্মী সজ্জিত করা হয়েছে।</li><li><strong>স্বাস্থ্যসেবা কর্মীর অধিকার এবং কর্তব্য</strong>: স্বাস্থ্যসেবা কর্মী অনুশীলন সুরক্ষা, যুক্তিসঙ্গত পারিশ্রমিক, পেশাদার প্রশিক্ষণ ইত্যাদি অধিকার উপভোগ করে, এবং একই সাথে রোগী উদ্ধার, রোগীকে সম্মান করা, চিকিৎসা গোপন রাখা ইত্যাদি কর্তব্য পালন করে।</li></ul><h2 id="_6-পাবলিক-স্বাস্থ্য-এবং-প্রতিরোধ" tabindex="-1">6. পাবলিক স্বাস্থ্য এবং প্রতিরোধ <a class="header-anchor" href="#_6-পাবলিক-স্বাস্থ্য-এবং-প্রতিরোধ" aria-label="Permalink to &quot;6. পাবলিক স্বাস্থ্য এবং প্রতিরোধ&quot;">​</a></h2><p>রাষ্ট্র পাবলিক স্বাস্থ্য ব্যবস্থা স্থাপন করে, এবং নিম্নলিখিত কার্য সম্পাদন করে:</p><ol><li>সংক্রামক রোগের পর্যবেক্ষণ এবং প্রতিরোধ ও নিয়ন্ত্রণ, আন্তঃ位面 মহামারী সতর্কতা ব্যবস্থা স্থাপন করা।</li><li>সার্বজনীন স্বাস্থ্য পরীক্ষা এবং স্বাস্থ্য রেকর্ড ব্যবস্থাপনা।</li><li>সাধনা নিরাপত্তা প্রচার এবং সাধনা ক্ষতি প্রতিরোধ নির্দেশনা।</li><li>পরিবেশ স্বাস্থ্য এবং খাদ্য ও ওষুধের নিরাপত্তা তদারকি।</li><li>আকস্মিক পাবলিক স্বাস্থ্য ঘটনার জরুরী প্রতিক্রিয়া।</li></ol><h2 id="_7-আইনি-দায়বদ্ধতা" tabindex="-1">7. আইনি দায়বদ্ধতা <a class="header-anchor" href="#_7-আইনি-দায়বদ্ধতা" aria-label="Permalink to &quot;7. আইনি দায়বদ্ধতা&quot;">​</a></h2><p>এই আইনের বিধান লঙ্ঘন করা কার্যক্রম, অপরাধের গুরুত্ব অনুযায়ী নিম্নলিখিত দায়বদ্ধতা গ্রহণ করবে:</p><ul><li>স্বাস্থ্যসেবা প্রতিষ্ঠান জরুরী রোগীকে প্রত্যাখ্যান করলে, সংশোধন করার নির্দেশ এবং জরিমানা, গুরুতর পরিণতি সৃষ্টি করলে অনুশীলন লাইসেন্স বাতিল।</li><li>স্বাস্থ্যসেবা কর্মী গুরুতর অসাবধানতার কারণে রোগীর ক্ষতি সাধন করলে, ক্ষতিপূরণের দায়বদ্ধতা গ্রহণ, গুরুতর অপরাধের ক্ষেত্রে অনুশীলনের যোগ্যতা বাতিল।</li><li>স্বাস্থ্যসেবা প্রতিষ্ঠান বিধি বিরোধী ফি আদায়, অতিরিক্ত চিকিৎসা করলে, ফি ফেরত দেওয়ার নির্দেশ এবং জরিমানা।</li><li>রোগীর স্বাস্থ্যসেবা গোপনীয়তা ফাঁস করলে, মানসিক ক্ষতি ক্ষতিপূরণ গ্রহণ, গুরুতর অপরাধের ক্ষেত্রে ফৌজদারি দায়বদ্ধতা আরোপ।</li><li>জাল ওষুধ, নিম্নমানের ওষুধ উৎপাদন বা বিক্রি করলে, অবৈধ আয় জব্দ এবং জরিমানা, অপরাধ গঠন করলে ফৌজদারি দায়বদ্ধতা আরোপ।</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>《স্বাস্থ্যসেবা নিশ্চয়তা আইন》 হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার &quot;প্রত্যেকের পথ&quot; দর্শনের স্বাস্থ্য ক্ষেত্রের প্রকাশ। এটি সর্বজনীনভাবে কভার করা স্বাস্থ্যসেবা নিশ্চয়তা ব্যবস্থা স্থাপন করা, সাধনা ক্ষতি বিশেষ বিভাগ স্থাপন করা, জরুরী চিকিৎসা অধিকার নিশ্চিত করার মাধ্যমে, নিশ্চিত করে যে প্রতিটি জীব অসুস্থ বা আহত হলে সময়মতো চিকিৎসা পেতে পারে, এবং সকল প্রজাতির সহযোগিতামূলক অগ্রগতির জন্য স্বাস্থ্যের ভিত্তি পাকাপোক্ত করে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>40-共生宪法总纲 (সিম্বায়োসিস সংবিধানের মূল নীতি)</li><li>38-共生医疗体系 (সিম্বায়োসিস স্বাস্থ্যসেবা ব্যবস্থা)</li><li>45-住房保障法 (আবাসন নিশ্চয়তা আইন)</li><li>08-人人有路保障体系 (প্রত্যেকের পথ নিশ্চয়তা ব্যবস্থা)</li></ul>',29)])])}const c=a(i,[["render",e]]);export{u as __pageData,c as default};
